async function r(a,t={}){const e=await fetch(a,{cache:"no-store",...t}),n=await e.text();let s;try{s=n?JSON.parse(n):{}}catch{throw new Error(`API returned invalid JSON (${e.status})`)}if(!e.ok)throw new Error(s.error||e.statusText);return s}async function i(){const a=await r("/api/map");if(!Array.isArray(a.origin)||!a.width||!a.height||!a.resolution)throw new Error("Map metadata unavailable");return a}const o=()=>r("/api/bounds");async function c(){const a=await r("/api/health");if(!a.ok||!a.services||!Array.isArray(a.vehicles))throw new Error("System health unavailable");return a}async function u(a){const t=await r("/api/simulation/faults",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(a)});if(!t.simulation_only||!Array.isArray(t.active))throw new Error("Simulation fault control unavailable");return t}async function l(){const a=await r("/api/tasks/side-work");if(!a.simulation_only||!Array.isArray(a.statuses))throw new Error("Side-work task control unavailable");return a}async function y(a){const t=await r("/api/tasks/side-work",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(a)});if(!t.simulation_only||!t.requested||!Array.isArray(t.statuses))throw new Error("Side-work task request was not accepted");return t}async function w(a){const t=await r(`/api/state?${new URLSearchParams(a)}`);if(!Array.isArray(t.latest)||!Array.isArray(t.density))throw new Error("Traffic history unavailable");return t}export{y as a,l as b,i as c,o as d,w as e,c as g,u as s};
